require __DIR__.'/../app/bootstrap.php';refresh_user();$user=require_login('admin');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$old=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$stmt=db()->prepare('SELECT password_hash FROM users WHERE id=?');$stmt->bind_param('i',$user['id']);$stmt->execute();$hash=$stmt->get_result()->fetch_column();if(!password_verify($old,(string)$hash)){flash('error','Current password was not correct.');}elseif(strlen($new)<12){flash('error','Choose a password with at least 12 characters.');}elseif($new!==$confirm){flash('error','New passwords do not match.');}else{$hash=password_hash($new,PASSWORD_DEFAULT);$stmt=db()->prepare('UPDATE users SET password_hash=? WHERE id=?');$stmt->bind_param('si',$hash,$user['id']);$stmt->execute();flash('success','Password updated.');}redirect('/admin/password.php');}render_header('Change Password','admin');page_title('Change password','Keep your administrator account protected.');?><div class="settings-card password-card"><form method="post" class="settings-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Current password<input type="password" name="current_password" required autocomplete="current-password"></label><label>New password<input type="password" name="new_password" minlength="12" required autocomplete="new-password"><small>Use at least 12 characters.</small></label><label>Confirm new password<input type="password" name="confirm_password" minlength="12" required autocomplete="new-password"></label><button class="button button-admin">Update password</button></form></div><?php render_footer();
